    pairs = [(s, t) for s in range(N) for t in range(s, N)]

    def all_equal(s, t):
        # The window a[s..t] holds one value.
        return And([a[k] == a[s] for k in range(s, t + 1)])

    # r is the length of some window whose elements are all equal.
    attained = Or([And(all_equal(s, t), r == t - s + 1) for (s, t) in pairs])

    # No window of uniform values is longer than r.
    maximal = And([Implies(all_equal(s, t), r >= t - s + 1) for (s, t) in pairs])

    return And(r >= 1, r <= N, attained, maximal)
